// Local lookup of reported critical-mineral sites.
//
// Runs in the browser with no network call, so these names resolve instantly and
// keep working when a public geocoder rate-limits us (the Nominatim instance
// returns HTTP 429 to shared IPs under light use — which is what made the search
// box come back empty for every Indian site name).
//
// Data is generated by product/build_gazetteer.py; coordinates there are
// geocoder-resolved town/district centroids, never hand-typed, and never the
// deposit outline.

import gazetteer from '../data/gazetteer.json'

export interface GazetteerSite {
  label: string
  commodity: 'lithium' | 'vanadium' | string
  region: string
  setting: string
  aliases: string[]
  lat: number
  lon: number
  resolved_from: string
  resolved_name: string
  geocoder: string
  precision: string
  /** Verbatim third-party claim. Never measured or verified by this system. */
  reported: string | null
}

export const GAZETTEER_NOTE: string = (gazetteer as any).note
/** Attribution that must accompany every `reported` figure shown in the UI. */
export const REPORTED_SOURCE: string = (gazetteer as any).reported_source
const SITES = (gazetteer as any).sites as GazetteerSite[]

/** Fold accents and punctuation so "Sāmbhar" matches "sambhar". */
function norm(s: string) {
  return s
    .normalize('NFD').replace(/[̀-ͯ]/g, '')
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, ' ')
    .trim()
}

/**
 * Match on label, aliases, region and setting. Hyphenated compound names are
 * split, so "Salal-Haimana" is findable by typing either half — which is how
 * people actually search for these.
 */
export function searchGazetteer(query: string, limit = 5): GazetteerSite[] {
  const q = norm(query)
  if (q.length < 2) return []

  const scored: { site: GazetteerSite; score: number }[] = []
  for (const site of SITES) {
    // Commodity included so typing "lithium" lists the lithium sites.
    const fields = [site.label, ...site.aliases, site.region, site.commodity]
    const tokens = fields.flatMap(f => norm(f).split(' ')).filter(Boolean)
    const haystack = norm(fields.join(' '))

    let score = 0
    if (tokens.some(t => t === q)) score = 100                 // exact token
    else if (tokens.some(t => t.startsWith(q))) score = 80     // token prefix
    else if (haystack.includes(q)) score = 60                  // anywhere
    else if (q.split(' ').every(w => haystack.includes(w))) score = 40  // all words

    if (score > 0) {
      // Prefer the shorter label when scores tie — it is usually the better match.
      scored.push({ site, score: score - site.label.length / 100 })
    }
  }

  return scored
    .sort((a, b) => b.score - a.score)
    .slice(0, limit)
    .map(s => s.site)
}

/**
 * The gazetteer site at a coordinate, if any — used to show the reported claim
 * for wherever the user currently is. 0.25 deg is generous on purpose: the
 * stored point is a town centroid, so a nearby analysis is still "this site".
 */
export function findSiteNear(lat: number, lon: number, tol = 0.25): GazetteerSite | null {
  let best: GazetteerSite | null = null
  let bestD = Infinity
  for (const s of SITES) {
    const d = Math.abs(s.lat - lat) + Math.abs(s.lon - lon)
    if (d < bestD && Math.abs(s.lat - lat) <= tol && Math.abs(s.lon - lon) <= tol) {
      best = s; bestD = d
    }
  }
  return best
}

/** True when optical sensing physically cannot see this target type. */
export function isUndetectable(site: GazetteerSite) {
  return /NOT detectable|marine, not land/i.test(site.setting)
}
